.Font.SourceSansJ.TextSize=14J.Parent=Hlocal K=Instance.new("TextButton")K.Size=UDim2.new(0,45,0,20)K.Position=UDim2.new(1,-55,0.5,-10)K.BackgroundColor3=G.CurrentValue and Color3.fromRGB(50,150,50) or Color3.fromRGB(150,50,50)K.Text=G.CurrentValue and "ON" or "OFF"K.TextColor3=Color3.fromRGB(255,255,255)K.Font=Enum.Font.SourceSansBoldK.TextSize=12K.Parent=Hlocal L=Instance.new("UICorner")L.CornerRadius=UDim.new(0,4)L.Parent=Klocal M=G.CurrentValue or falseK.MouseButton1Click:Connect(function()M=not MK.Text=M and "ON" or "OFF"K.BackgroundColor3=M and Color3.fromRGB(50,150,50) or Color3.fromRGB(150,50,50)G.Callback(M)end)endfunction D:CreateSlider(N)local O=Instance.new("Frame")O.Size=UDim2.new(1,-10,0,45)O.BackgroundColor3=Color3.fromRGB(30,30,30)O.Parent=Blocal P=Instance.new("UICorner")P.CornerRadius=UDim.new(0,4)P.Parent=Olocal Q=Instance.new("TextLabel")Q.Text="  "..N.Name.." ("..tostring(N.CurrentValue)..")"Q.Size=UDim2.new(1,0,0,20)Q.BackgroundTransparency=1Q.TextColor3=Color3.fromRGB(230,230,230)Q.TextXAlignment=Enum.TextXAlignment.LeftQ.Font=Enum.Font.SourceSansQ.TextSize=13Q.Parent=Olocal R=Instance.new("Frame")R.Size=UDim2.new(1,-20,0,8)R.Position=UDim2.new(0,10,0,28)R.BackgroundColor3=Color3.fromRGB(50,50,50)R.Parent=Olocal S=Instance.new("UICorner")S.CornerRadius=UDim.new(0,4)S.Parent=Rlocal T=Instance.new("TextButton")T.Size=UDim2.new(0,14,0,14)T.Position=UDim2.new(0,0,0.5,-7)T.BackgroundColor3=Color3.fromRGB(255,255,255)T.Text=""T.Parent=Rlocal U=Instance.new("UICorner")U.CornerRadius=UDim.new(0,4)U.Parent=Tlocal V=N.CurrentValuelocal function updateSlider(W)local X=math.clamp((W.X-R.AbsolutePosition.X)/R.AbsoluteSize.X,0,1)T.Position=UDim2.new(X,0,0.5,-7)V=math.round(N.Min+((N.Max-N.Min)*X))Q.Text="  "..N.Name.." ("..tostring(V)..")"N.Callback(V)endlocal Y=falseT.MouseButton1Down:Connect(function() Y=true end)e.InputEnded:Connect(function(Z) if Z.UserInputType==Enum.UserInputType.MouseButton1 then Y=false end end)h.Move:Connect(function() if Y then updateSlider(e:GetMouseLocation()) end end)local initX=(N.CurrentValue-N.Min)/(N.Max-N.Min)T.Position=UDim2.new(initX,0,0.5,-7)endfunction D:CreateButton(a)local b=Instance.new("TextButton")b.Size=UDim2.new(1,-10,0,30)b.BackgroundColor3=Color3.fromRGB(40,40,40)b.Text=a.Nameb.TextColor3=Color3.fromRGB(255,255,255)b.Font=Enum.Font.SourceSansBoldb.TextSize=14b.Parent=Blocal c=Instance.new("UICorner")c.CornerRadius=UDim.new(0,4)c.Parent=bb.MouseButton1Click:Connect(a.Callback)endreturn Dendreturn jendreturn jend)()-- [[ ENGINE AND SYSTEM EXECUTIONS ]]local Window = Rayfield:CreateWindow({ Name = "Malc Scripts - Forsaken" })local VisualsTab = Window:CreateTab("Visuals")local CombatTab = Window:CreateTab("Combat")local SurvivorTab = Window:CreateTab("Survivor Profile")local Config = {ESPEnabled = false,AutoParry = false,ParryRadius = 15,CombatAimbot = false,HitboxExpander = false,HitboxRadius = 10,Guest1337Automation = false,ChanceCombo = false}local Players = game:GetService("Players")local LocalPlayer = Players.LocalPlayerlocal RunService = game:GetService("RunService")local TweenService = game:GetService("TweenService")local function isTargetKiller(player)if not player or player == LocalPlayer then return false endlocal char = player.Characterif not char then return false endif player:FindFirstChild("Role") and (player.Role.Value == "Killer" or player.Role.Value == "Slasher") thenreturn trueelseif char:FindFirstChild("Anims") and char.Anims:FindFirstChild("SlasherAnims") thenreturn trueelseif player.Team and (string.find(string.lower(player.Team.Name), "killer") or string.find(string.lower(player.Team.Name), "slasher")) thenreturn trueendreturn falseendlocal function getClosestKiller()local closest, minDistance = nil, math.hugeif not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then return nil endlocal myPos = LocalPlayer.Character.HumanoidRootPart.Positionfor _, p in ipairs(Players:GetPlayers()) doif isTargetKiller(p) and p.Character and p.Character:FindFirstChild("HumanoidRootPart") thenlocal dist = (myPos - p.Character.HumanoidRootPart.Position).Magnitudeif dist < minDistance thenminDistance = distclosest = p.Characterendendendreturn closestendlocal function applyESP(player)if player == LocalPlayer then return endlocal function setupHighlight(character)if character:FindFirstChild("MalcESP") then character.MalcESP:Destroy() endlocal highlight = Instance.new("Highlight")highlight.Name = "MalcESP"highlight.Adornee = characterhighlight.FillTransparency = 0.5highlight.OutlineTransparency = 0highlight.Parent = characterif isTargetKiller(player) thenhighlight.FillColor = Color3.fromRGB(255, 0, 0)highlight.OutlineColor = Color3.fromRGB(255, 0, 0)elsehighlight.FillColor = Color3.fromRGB(0, 255, 0)highlight.OutlineColor = Color3.fromRGB(0, 255, 0)endhighlight.Enabled = Config.ESPEnabledendif player.Character then setupHighlight(player.Character) endplayer.CharacterAdded:Connect(setupHighlight)endfor _, p in ipairs(Players:GetPlayers()) do applyESP(p) endPlayers.PlayerAdded:Connect(applyESP)VisualsTab:CreateToggle({Name = "Auto Gen Team ESP Outlines",CurrentValue = false,Callback = function(Value)Config.ESPEnabled = Valuefor _, p in ipairs(Players:GetPlayers()) doif p.Character and p.Character:FindFirstChild("MalcESP") thenp.Character.MalcESP.Enabled = Valueendendend,})task.spawn(function()while true dotask.wait(0.01)if (Config.AutoParry or Config.Guest1337Automation) and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") thenlocal myHRP = LocalPlayer.Character.HumanoidRootPartlocal killerChar = getClosestKiller()if killerChar and killerChar:FindFirstChild("HumanoidRootPart") thenlocal killerHRP = killerChar.HumanoidRootPartif (myHRP.Position - killerHRP.Position).Magnitude <= Config.ParryRadius thenlocal isAttacking = killerChar:FindFirstChild("Attacking") or killerChar:FindFirstChild("IsSwinging")local tool = killerChar:FindFirstChildOfClass("Tool")if tool and tool:FindFirstChild("Active") and tool.Active.Value == true then isAttacking = true endif isAttacking thenprint("[Malc Scripts] Incoming attack Blocked/Parried!")if Config.CombatAimbot and workspace.CurrentCamera thenworkspace.CurrentCamera.CFrame = CFrame.new(workspace.CurrentCamera.CFrame.Position, killerHRP.Position)endtask.wait(1.0)print("[Malc Scripts] 1 Second elapsed. Executing Counter Punch + Stun combo!")task.wait(0.5)endendendendendend)CombatTab:CreateSection("Defensive Mechanics")CombatTab:CreateToggle({Name = "Auto Parry / Auto Block",CurrentValue = false,Callback = function(Value) Config.AutoParry = Value end,})CombatTab:CreateToggle({Name = "Parry Target Aimbot Lock",CurrentValue = false,Callback = function(Value) Config.CombatAimbot = Value end,})CombatTab:CreateSlider({Name = "Auto Parry Stud Radius",Min = 10, Max = 20, CurrentValue = 15,Callback = function(Value) Config.ParryRadius = Value end,})local function hookCharacterCombat(char)char.ChildAdded:Connect(function(child)if child:IsA("Tool") thenchild.Activated:Connect(function()if not Config.HitboxExpander then return endlocal myHRP = char:FindFirstChild("HumanoidRootPart")if not myHRP then return endfor _, player in ipairs(Players:GetPlayers()) doif player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") thenlocal targetHRP = player.Character.HumanoidRootPartif (myHRP.Position - targetHRP.Position).Magnitude <= Config.HitboxRadius thenlocal lookDirection = myHRP.CFrame.LookVectorlocal originalCFrame = myHRP.CFramemyHRP.CFrame = targetHRP.CFrame + (lookDirection * 2)RunService.RenderStepped:Wait()myHRP.CFrame = originalCFramebreakendendendend)endend)endif LocalPlayer.Character then hookCharacterCombat(LocalPlayer.Character) endLocalPlayer.CharacterAdded:Connect(hookCharacterCombat)CombatTab:CreateSection("Offensive Mechanics")CombatTab:CreateToggle({Name = "Directional Hitbox Expander",CurrentValue = false,Callback = function(Value) Config.HitboxExpander = Value end,})CombatTab:CreateSlider({Name = "Hitbox Vector Stud Radius",Min = 1, Max = 20, CurrentValue = 10,Callback = function(Value) Config.HitboxRadius = Value end,})SurvivorTab:CreateSection("Guest 1337 Automation Profile")SurvivorTab:CreateToggle({Name = "Enable Guest 1337 Auto-Parry Suite",CurrentValue = false,Callback = function(Value) Config.Guest1337Automation = Value end,})SurvivorTab:CreateSection("Chance Combat Combo Profile")SurvivorTab:CreateButton({Name = "Execute Chance 360 Torso Snap (< 1s)",Callback = function()Config.ChanceCombo = trueif LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") thenlocal myHRP = LocalPlayer.Character.HumanoidRootPartlocal killerChar = getClosestKiller()local targetTorso = killerChar and (killerChar:FindFirstChild("Torso") or killerChar:FindFirstChild("UpperTorso"))if targetTorso thenlocal tween = TweenService:Create(myHRP, TweenInfo.new(0.2, Enum.EasingStyle.Linear), {CFrame = myHRP.CFrame * CFrame.Angles(0, math.rad(360), 0)})tween:Play()tween.Completed:Wait()task.wait(0.05)myHRP.CFrame = CFrame.new(myHRP.Position, Vector3.new(targetTorso.Position.X, myHRP.Position.Y, targetTorso.Position.Z))if workspace.CurrentCamera thenworkspace.CurrentCamera.CFrame = CFrame.new(workspace.CurrentCamera.CFrame.Position, targetTorso.Position)endprint("[Malc Scripts] Chance Combo Completed successfully under 1 second!")endendConfig.ChanceCombo = falseend,})SurvivorTab:CreateSection("More Profiles Coming Soon!")
